// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Game {
    struct Player { uint256 score; }
    mapping(address => Player) public players;

    function addScore() external {
        Player storage p = players[msg.sender];
        p.score += 10;
    }
}

