production.solution:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract WebhookRegistry {
    struct Config {
        string webhookUrl;
        uint256 callsMade;
    }
    mapping(address => Config) public configs;

    function registerWebhook(string calldata url) external {
        configs[msg.sender] = Config(url, 0);
    }

    function logCall() external {
        Config storage c = configs[msg.sender];
        c.callsMade += 1;
    }

    function getCalls(address client) external view returns (uint256) {
        return configs[client].callsMade;
    }
}
